# Construct the Levi graph of PG(2,3)
# Points and lines of the projective plane of order 3

# We can represent points as non-zero vectors in GF(3)^3 modulo scalar multiplication.
# Since GF(3) has scalars {1,2} and 2 = -1, each 1-dim subspace has 2 non-zero vectors.
# We can take canonical representatives: vectors whose first non-zero coordinate is 1.

points = []
for x in range(3):
    for y in range(3):
        for z in range(3):
            if (x,y,z) != (0,0,0):
                # canonical: first non-zero is 1
                if x != 0:
                    if x == 1:
                        points.append((x,y,z))
                elif y != 0:
                    if y == 1:
                        points.append((x,y,z))
                else:
